actionConfiguration.body:
update requests set title = {{RequestTitleInput.text}}, client_id = nullif({{RequestClientSelect.selectedOptionValue}}, '')::int,
  equipment_id = nullif({{RequestEquipmentSelect.selectedOptionValue}}, '')::int, status = {{RequestStatusSelect.selectedOptionValue}},
  assignee = {{RequestAssigneeSelect.selectedOptionValue}}, submitted = nullif({{RequestSubmittedInput.text}}, '')::date,
  due = nullif({{RequestDueInput.text}}, '')::date, save_location = {{RequestSaveInput.text}}, notes = {{RequestNotesInput.text}},
  updated_at = now(), updated_by = {{appsmith.user.email}}
where id = {{appsmith.URL.queryParams.id}};
